      bIter = b.iterator();
      while (bIter.hasNext())
      {
         bIter.next(); if (bIter.hasNext())
         {
            bIter.next(); bIter.remove(); }
      }

      System.out.println(b);

      a.removeAll(b);

      System.out.println(a);
   }
