package com.brianway.learning.java.multithread.lock.example3;




public class MyService {
    private ReentrantLock lock = new ReentrantLock();
    private Condition condition = lock.newCondition();
    private boolean hasValue = false;

    public void set() {
        try {
            lock.lock();
            while (hasValue == true) {
                System.out.println("æå¯è½ââè¿ç»­" + "  æ¶é´ä¸º" + System.currentTimeMillis() + " ThreadName=" + Thread.currentThread().getName());
                condition.await();
            }
            System.out.println("æå°â" + "          æ¶é´ä¸º" + System.currentTimeMillis() + " ThreadName=" + Thread.currentThread().getName());
            hasValue = true;
            condition.signalAll();
        } catch (InterruptedException e) {
            e.printStackTrace();
        } finally {
            System.out.println("set unlock" + "      æ¶é´ä¸º" + System.currentTimeMillis() + " ThreadName=" + Thread.currentThread().getName());
            lock.unlock();
        }
    }

    public void get() {
        try {
            lock.lock();
            while (hasValue == false) {
                System.out.println("æå¯è½ââè¿ç»­" + "  æ¶é´ä¸º" + System.currentTimeMillis() + " ThreadName=" + Thread.currentThread().getName());
                condition.await();
            }
            System.out.println("æå°â" + "          æ¶é´ä¸º" + System.currentTimeMillis() + " ThreadName=" + Thread.currentThread().getName());
            hasValue = false;
            condition.signalAll();
        } catch (InterruptedException e) {
            e.printStackTrace();
        } finally {
            System.out.println("get unlock" + "      æ¶é´ä¸º" + System.currentTimeMillis() + " ThreadName=" + Thread.currentThread().getName());
            lock.unlock();
        }
    }

}
