public class IncrementarDe7en7ConDoWhile {
  public static void main(String[] args) {   

    Scanner teclado = new Scanner(System.in); 

    System.out.println("Escribe un numero:");
    int num1 = teclado.nextInt();

    System.out.println("Escribe otro numero:");
    int num2 = teclado.nextInt();
    System.out.println("==================================================");

    if (num1 == num2){
      System.err.println("Escribe 2 numeros distinctos por favor!"); 
    } else if(num1 > num2){
        int aux = num1;
        num1 = num2;
        num2 = aux;

        for (int i = num1; i <= num2; i += 7){
          System.out.println(i + " ");
        }

        System.err.println("El primer numero tiene que ser mas pequeÃ±os que el segundo"); 
        System.err.println("Asi que hemos rotado los numeros");
    }else{
        int i = num1;
       do{
          System.out.println(i + " ");
          i += 7;
       } while (i <= num2);
    }
  }
}
