public class Solution {
    public int calculateMinimumHP(int[][] dungeon) {
        int M = dungeon.length;
        if (M == 0) return 0;
        int N = dungeon[0].length;
        int[][] dp = new int[M][N];
        dp[M-1][N-1] = 1 - Math.min(0, dungeon[M-1][N-1]);
        for (int i = M - 2; i >= 0; --i) {
            if (dp[i+1][N-1] - dungeon[i][N-1] <= 0) dp[i][N-1] = 1;
            else dp[i][N-1] = dp[i+1][N-1] - dungeon[i][N-1]; 
        }
        for (int j = N - 2; j >= 0; --j) {
            if (dp[M-1][j+1] - dungeon[M-1][j] <= 0) dp[M-1][j] = 1;
            else dp[M-1][j] = dp[M-1][j+1] - dungeon[M-1][j];
        }
        for (int i = M - 2; i >= 0; --i) {
            for (int j = N - 2; j >= 0; --j) {
                int val = Math.min(dp[i+1][j], dp[i][j+1]);
                if (dungeon[i][j] >= val) dp[i][j] = 1;
                else dp[i][j] = val - dungeon[i][j];
            }
        }
        return Math.max(1,dp[0][0]); 
    }
},31

public class Solution {
    public ListNode getIntersectionNode(ListNode headA, ListNode headB) {
        ListNode cur = headA;
        int lenA = 0, lenB = 0;
        while (cur != null) {
            ++lenA;
            cur = cur.next;
        }
        cur = headB;
        while (cur != null) {
            ++lenB;
            cur = cur.next;
        }
        if (lenA >= lenB) {
            int diff = lenA - lenB;
            while (diff > 0) {
                headA = headA.next;
                --diff;
            }
            while (headA != null && headB != null) {
                if(headA == headB) {
                    return headA;
                }
                headA = headA.next;
                headB = headB.next;
            }
        } else {
            int diff = lenB - lenA;
            while (diff > 0) {
                headB = headB.next;
                --diff;
            }
            while (headA != null && headB != null) {
                if(headA == headB) {
                    return headA;
                }
                headA = headA.next;
                headB = headB.next;
            }
        }
        return null;
    }
