public class TextDemo2 {
    public static void main(String[] args) {
        Frame f = new Frame("Êý¾Ý×ªÒÆ");
        f.setBounds(500, 250, 400, 300);
        f.setLayout(new FlowLayout());

        final TextField tf = new TextField(20);
        Button bu = new Button("Ð´µ½ÎÄ±¾ÎÄ¼þ");
        Button bu2 = new Button("¶ÁÈ¡ÎÄ±¾ÎÄ¼þ");
        final TextArea ta = new TextArea(10, 40);

        f.add(tf);
        f.add(bu);
        f.add(bu2);
        f.add(ta);

        f.addWindowListener(new WindowAdapter() {
            @Override
            public void windowClosing(WindowEvent e) {
                System.exit(0);
            }
        });

        bu.addActionListener(new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent e) {
                String tf_str = tf.getText();
                tf.setText("");

                BufferedWriter bw = null;
                try {
                    bw = new BufferedWriter(new FileWriter("bw.txt", true));
                    bw.write(tf_str);
                    bw.newLine();
                    bw.flush();
                } catch (IOException e1) {
                    e1.printStackTrace();
                } finally {
                    if (bw != null) {
                        try {
                            bw.close();
                        } catch (IOException e1) {
                            e1.printStackTrace();
                        }
                    }
                }
            }
        });

        bu2.addActionListener(new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent e) {
                ta.setText("");

                BufferedReader br = null;
                try {
                    br = new BufferedReader(new FileReader("bw.txt"));
                    String line = null;
                    while ((line = br.readLine()) != null) {
                        ta.append(line + "\n");
                    }
                } catch (IOException e1) {
                    e1.printStackTrace();
                } finally {
                    if (br != null) {
                        try {
                            br.close();
                        } catch (IOException e1) {
                            e1.printStackTrace();
                        }
                    }
                }
            }
        });

        f.setVisible(true);
    }
}
